-- SECURITY DEFINER; API roles that may call it: authenticated, service_role
CREATE OR REPLACE FUNCTION public.reopen_invoice(p_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare inv record;
begin
  if not public.is_global_admin() then
    raise exception 'Only the team can reopen an invoice.';
  end if;
  select * into inv from public.invoices where id = p_id;
  if inv is null then raise exception 'No such invoice.'; end if;
  if inv.stage in ('sent', 'paid') then
    raise exception 'That invoice has already gone out. Raise a corrected one instead.';
  end if;

  update public.invoices set
    stage = 'awaiting_approval', status = 'awaiting_approval',
    decided_at = null, decided_by = null, decision_note = null
  where id = p_id;

  perform public.resnapshot_invoice(p_id);
end $function$;
